package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;
import org.springframework.core.env.*;
final class CustomerRepliesAcceptance {
 static String route(String id){return "/api/openservice/customer-cases/"+id+"/replies";}
 static String prefs(){return "/api/openservice/customer-service/notifications";}
 static Map<String,Object> get(WorkflowSupport h,String id,String user)throws Exception{return CustomerCasesAcceptance.get(h,route(id),user);}
 static Map<String,Object> body(WorkflowSupport h,String id,boolean email)throws Exception{return map("record_revision",Integer.parseInt(object(get(h,id,"CustomerAgent").get("record")).get("sys_mod_count").toString()),"key",Values.id(),"body","Public reply <script>safe</script>","email",email);}
 static Map<String,Object> publish(WorkflowSupport h,String id,Map<String,Object> body)throws Exception{var r=h.json("POST",route(id),body,auth("CustomerAgent"));assertEquals(200,r.statusCode(),html(r));return object(parsed(r).get("result"));}
 static String[] setup(WorkflowSupport h)throws Exception{var ids=CustomerCasesAcceptance.setup(h);String ent=CustomerCasesAcceptance.entitlement(h,ids[0],0);String id=CustomerCasesAcceptance.create(h,ent,CustomerCasesAcceptance.body(h,ent,"CustomerOne"),"CustomerOne").get("sys_id").toString();return new String[]{id,ids[0],ids[1],ids[2],ids[4]};}
 static void verified(Store store)throws Exception{try(var db=store.open()){db.update("UPDATE os_user SET email='customer@example.invalid',email_verified=1 WHERE name='CustomerOne'");db.connection.commit();}}
 static void preference(WorkflowSupport h,boolean enabled)throws Exception{var p=CustomerCasesAcceptance.get(h,prefs(),"CustomerOne");var r=h.json("POST",prefs(),map("revision",p.get("revision"),"enabled",enabled),auth("CustomerOne"));assertEquals(200,r.statusCode(),html(r));}
 static void enable(Environment env,boolean enabled){((ConfigurableEnvironment)env).getPropertySources().addFirst(new MapPropertySource("customer-reply-test",Map.of("DELIVERY_ENABLED",enabled,"PUBLIC_BASE_URL","https://example.invalid")));}
 static void reset(Environment env){((ConfigurableEnvironment)env).getPropertySources().remove("customer-reply-test");}
 static Map<String,Object> job(Store store)throws Exception{try(var db=store.open()){return db.one("SELECT * FROM os_outbox WHERE kind='email.customer_reply' ORDER BY created_at DESC,job_id DESC LIMIT 1");}}
 static void run(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(false,get(h,id,"CustomerAgent").get("can_email"));assertEquals(false,get(h,id,"CustomerOne").get("can_publish"));assertEquals(0,CustomerCasesAcceptance.get(h,prefs(),"CustomerOne").get("revision"));assertEquals(false,CustomerCasesAcceptance.get(h,prefs(),"CustomerOne").get("verified_email"));verified(h.store);preference(h,true);enable(h.environment,true);
  try{assertEquals(true,get(h,id,"CustomerAgent").get("can_email"));assertEquals(302,h.protectedForm("/record/customer_case/"+id+"/note",map("body","Staff secret must stay internal"),auth("CustomerAgent")).statusCode());var body=body(h,id,false);var result=publish(h,id,body);var reply=objects(result.get("replies")).getFirst();assertEquals("portal",reply.get("delivery"));assertEquals(body.get("body"),reply.get("body"));assertEquals(1,objects(publish(h,id,body).get("replies")).size());body.put("body","Changed key reuse");assertEquals(409,h.json("POST",route(id),body,auth("CustomerAgent")).statusCode());assertFalse(JSON.writeValueAsString(get(h,id,"CustomerOne")).contains("Staff secret"));assertFalse(JSON.writeValueAsString(result).contains("customer@example.invalid"));
   var concurrent=body(h,id,true);concurrent.put("body","Public reply number two");var a=CompletableFuture.supplyAsync(()->{try{return h.json("POST",route(id),concurrent,auth("CustomerAgent"));}catch(Exception e){throw new RuntimeException(e);}});var b=CompletableFuture.supplyAsync(()->{try{return h.json("POST",route(id),concurrent,auth("CustomerAgent"));}catch(Exception e){throw new RuntimeException(e);}});assertEquals(200,a.get().statusCode());assertEquals(200,b.get().statusCode());try(var db=h.store.open()){db.update("UPDATE os_customer_reply SET created=? WHERE record_id=?","2026-11-18T00:00:00Z",id);db.connection.commit();}assertEquals("Public reply number two",objects(get(h,id,"CustomerOne").get("replies")).getLast().get("body"));assertEquals(2,objects(get(h,id,"CustomerOne").get("replies")).size());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_outbox WHERE kind='email.customer_reply'"));}var job=job(h.store);assertFalse(job.get("envelope").toString().contains("Public reply"));
   try(var sink=new MailSink()){var worker=new DeliveryWorker(new Store(h.environment),new SmtpDelivery(OutboxTest.mail(sink)));assertTrue(worker.runOne(System.currentTimeMillis()+100));String message=sink.receive();assertTrue(message.contains("OpenService customer support reply"));assertTrue(message.contains("Public reply"));assertTrue(message.contains("https://example.invalid/record/customer_case/"+id+"/replies"));assertTrue(message.contains("Message-ID: <"+job.get("job_id")+"@openservice.invalid>"));assertFalse(message.contains("Staff secret"));}assertEquals("delivered",objects(get(h,id,"CustomerOne").get("replies")).getLast().get("delivery"));assertEquals("",job(h.store).get("envelope"));assertEquals(200,h.get("/api/openservice/delivery?kind=customer_reply",auth("admin")).statusCode());new Store(h.environment);assertEquals(2,objects(get(h,id,"CustomerAgent").get("replies")).size());try(var db=h.store.open()){db.update("DELETE FROM os_outbox WHERE kind='email.customer_reply'");db.connection.commit();}assertEquals("unavailable",objects(get(h,id,"CustomerOne").get("replies")).getLast().get("delivery"));
  }finally{reset(h.environment);}
 }
 static void delivery(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];verified(h.store);preference(h,true);enable(h.environment,true);
  try{var original=ServiceSchema(h);for(String change:List.of("preference","email","verified","active","role","password","contact","account","field","delete")){
    if(change.equals("delete")){String ent=CustomerCasesAcceptance.entitlement(h,ids[1],0);id=CustomerCasesAcceptance.create(h,ent,CustomerCasesAcceptance.body(h,ent,"CustomerOne"),"CustomerOne").get("sys_id").toString();}publish(h,id,body(h,id,true));var payload=Outbox.decrypt(h.store.secret,job(h.store).get("envelope").toString());try(var db=h.store.open()){String viewer=RecordAccess.owner(db,"admin");db.viewerId=viewer;db.viewerRole="admin";assertTrue(CustomerReplies.valid(db,payload));assertEquals(viewer,db.viewerId);assertEquals("admin",db.viewerRole);for(String key:List.of("email","body","path","type","reply_id")){var altered=new LinkedHashMap<>(payload);altered.put(key,"wrong");assertFalse(CustomerReplies.valid(db,altered));}}
    switch(change){case "preference"->preference(h,false);case "contact"->CustomerCasesAcceptance.contact(h,ids[2],"CustomerOne",true);case "account"->CustomerCasesAcceptance.manage(h,ids[1],CustomerCasesAcceptance.accountBody(h,ids[1],false,ids[3]));case "field"->{var schema=new LinkedHashMap<>(original);schema.put("field_rules",map("description",map("read_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"customer_case",schema);}case "delete"->assertEquals(204,h.json("DELETE","/api/now/table/customer_case/"+id,map(),auth("admin")).statusCode());default->{try(var db=h.store.open()){String update=switch(change){case "email"->"email='other@example.invalid'";case "verified"->"email_verified=0";case "active"->"active=0";case "role"->"role='reader'";default->"password_reset_required=1";};db.update("UPDATE os_user SET "+update+" WHERE name='CustomerOne'");db.connection.commit();}}}
    var worker=new DeliveryWorker(h.store,(a,b)->fail("Unavailable recipient must not receive a reply"));assertTrue(worker.runOne(System.currentTimeMillis()+100));assertEquals("cancelled",job(h.store).get("state"));assertEquals("LINK_UNAVAILABLE",job(h.store).get("error"));assertEquals("",job(h.store).get("envelope"));try(var db=h.store.open()){db.update("UPDATE os_user SET email='customer@example.invalid',email_verified=1,active=1,role='requester',password_reset_required=0 WHERE name='CustomerOne'");db.connection.commit();}preference(h,true);CustomerCasesAcceptance.contact(h,ids[1],"CustomerOne",true);CustomerCasesAcceptance.manage(h,ids[1],CustomerCasesAcceptance.accountBody(h,ids[1],true,ids[3]));ReferencePickerAcceptance.writeSchema(h,"customer_case",original);
   }
  }finally{reset(h.environment);}
 }
 static Map<String,Object> ServiceSchema(WorkflowSupport h)throws Exception{try(var db=h.store.open()){return Service.schema(db,"customer_case");}}
 static void authority(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var original=ServiceSchema(h);var body=body(h,id,false);try(var db=h.store.open()){db.viewerId=RecordAccess.owner(db,"CustomerOne");db.viewerRole="requester";assertEquals(403,assertThrows(Failure.class,()->CustomerReplies.publish(h.store,db,id,body)).status);}
  for(String user:List.of("CustomerOne","CustomerTwo","CustomerReader"))assertEquals(403,h.json("POST",route(id),body,auth(user)).statusCode());for(String user:List.of("CustomerTwo","CustomerOther","CustomerOutsider"))assertEquals(404,h.get(route(id),auth(user)).statusCode());for(String user:List.of("admin","CustomerAgent","CustomerReader")){assertEquals(403,h.get(prefs(),auth(user)).statusCode());assertEquals(403,h.json("POST",prefs(),map("revision",0,"enabled",true),auth(user)).statusCode());}
  for(String permission:List.of("read","write","update")){var changed=new LinkedHashMap<>(original);if(permission.equals("update"))changed.put("record_roles",map("update",List.of("admin")));else changed.put("field_rules",map("description",map(permission+"_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"customer_case",changed);try{assertEquals(403,h.json("POST",route(id),body,auth("CustomerAgent")).statusCode());if(permission.equals("read"))assertEquals(403,h.get(route(id),auth("CustomerAgent")).statusCode());else assertEquals(false,get(h,id,"CustomerAgent").get("can_publish"));}finally{ReferencePickerAcceptance.writeSchema(h,"customer_case",original);}}
  var allowed=new LinkedHashMap<>(original);allowed.put("field_rules",map("description",map("write_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"customer_case",allowed);assertEquals(true,get(h,id,"CustomerAgent").get("can_publish"));ReferencePickerAcceptance.writeSchema(h,"customer_case",original);
  RecordScopesAcceptance.member(h,ids[3],ids[4],false);assertEquals(404,h.json("POST",route(id),body,auth("CustomerAgent")).statusCode());RecordScopesAcceptance.member(h,ids[3],ids[4],true);publish(h,id,body);CustomerCasesAcceptance.contact(h,ids[2],"CustomerOne",true);assertEquals(404,h.get(route(id),auth("CustomerOne")).statusCode());assertFalse(html(h.get("/api/now/table/customer_case",auth("CustomerOne"))).contains(id));CustomerCasesAcceptance.contact(h,ids[1],"CustomerOne",true);
  var mail=body(h,id,true);assertEquals(409,h.json("POST",route(id),mail,auth("CustomerAgent")).statusCode());enable(h.environment,true);try{assertEquals(false,get(h,id,"CustomerAgent").get("can_email"));assertEquals(409,h.json("POST",route(id),mail,auth("CustomerAgent")).statusCode());verified(h.store);assertEquals(409,h.json("POST",route(id),mail,auth("CustomerAgent")).statusCode());preference(h,true);var held=body(h,id,true);h.json("PATCH","/api/now/table/customer_case/"+id,map("priority","2"),auth("CustomerAgent"));assertEquals(409,h.json("POST",route(id),held,auth("CustomerAgent")).statusCode());}finally{reset(h.environment);}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var valid=body(h,id,false);for(String path:List.of(route(id),prefs())){assertEquals(405,h.json("PATCH",path,map(),auth("admin")).statusCode());assertEquals(400,h.get(path+"?x=1",auth("CustomerOne")).statusCode());assertEquals(400,h.json("POST",path+"?x=1",map(),auth("CustomerAgent")).statusCode());}assertEquals(404,h.get(route(Values.id()),auth("admin")).statusCode());for(var invalid:List.of(map(),map("revision",0),map("revision",0,"enabled","true"),map("revision",-1,"enabled",true))){assertEquals(400,h.json("POST",prefs(),invalid,auth("CustomerOne")).statusCode());}preference(h,true);assertEquals(409,h.json("POST",prefs(),map("revision",0,"enabled",false),auth("CustomerOne")).statusCode());assertEquals(400,h.protectedForm("/customer-service/notifications",map("revision","1","enabled","bad"),auth("CustomerOne")).statusCode());assertEquals(302,h.protectedForm("/customer-service/notifications",map("revision","1","enabled","false"),auth("CustomerOne")).statusCode());
  for(var invalid:List.of(map(),map("extra",1)))assertEquals(400,h.json("POST",route(id),invalid,auth("CustomerAgent")).statusCode());for(String key:List.of("body","key","email","record_revision")){var b=new LinkedHashMap<>(valid);b.put(key,switch(key){case "email"->"true";case "record_revision"->-1;default->" ";});assertEquals(400,h.json("POST",route(id),b,auth("CustomerAgent")).statusCode());}for(String key:List.of("body","key")){var b=new LinkedHashMap<>(valid);b.put(key,"x".repeat(key.equals("body")?4001:33));assertEquals(400,h.json("POST",route(id),b,auth("CustomerAgent")).statusCode());}var b=new LinkedHashMap<>(valid);b.put("key","invalid-key");assertEquals(400,h.json("POST",route(id),b,auth("CustomerAgent")).statusCode());b=new LinkedHashMap<>(valid);b.put("email","bad");assertEquals(400,h.protectedForm("/record/customer_case/"+id+"/replies",b,auth("CustomerAgent")).statusCode());valid.put("body","x".repeat(4000));assertEquals(4000,objects(publish(h,id,valid).get("replies")).getFirst().get("body").toString().length());assertEquals(200,h.get("/record/customer_case/"+id+"/replies",auth("CustomerOne")).statusCode());
 }
 static void limits(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];verified(h.store);preference(h,true);enable(h.environment,true);try{for(int i=0;i<5;i++){if(i==0)publish(h,id,body(h,id,true));try(var db=h.store.open()){db.update("UPDATE os_outbox SET available_at=0 WHERE kind='email.customer_reply'");db.connection.commit();}assertTrue(new DeliveryWorker(h.store,(a,b)->{throw new IllegalStateException("private transport error");}).runOne(System.currentTimeMillis()+100));}assertEquals("failed",job(h.store).get("state"));String job=job(h.store).get("job_id").toString();assertEquals(200,h.json("POST","/api/openservice/delivery/"+job+"/retry",map(),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_outbox SET expires_at=0 WHERE job_id=?",job);db.connection.commit();}assertFalse(new DeliveryWorker(h.store,(a,b)->fail()).runOne(System.currentTimeMillis()+100));assertEquals("cancelled",job(h.store).get("state"));
   var valid=body(h,id,true);try(var db=h.store.open()){for(int i=0;i<1000;i++)DeliveryOperationsAcceptance.seed(db,"queued",1,Long.MAX_VALUE,Long.MAX_VALUE);db.connection.commit();}assertEquals(429,h.json("POST",route(id),valid,auth("CustomerAgent")).statusCode());assertEquals(1,objects(get(h,id,"CustomerOne").get("replies")).size());assertEquals(valid.get("record_revision").toString(),object(get(h,id,"CustomerAgent").get("record")).get("sys_mod_count"));try(var db=h.store.open()){db.update("DELETE FROM os_outbox");for(int i=1;i<200;i++)db.update("INSERT INTO os_customer_reply VALUES(?,?,?,?,?,?,?,?,?,?)",Values.id(),id,ids[4],"Support",i+1,"Retained reply",now(),Values.id(),"hash","");db.connection.commit();}assertEquals(200,objects(get(h,id,"CustomerAgent").get("replies")).size());assertEquals(400,h.json("POST",route(id),body(h,id,false),auth("CustomerAgent")).statusCode());
  }finally{reset(h.environment);}
 }
}
